-- GenDB engine variant Q03-commuted_comparisons: template q03.sql, kind commuted_comparisons (generated by generate.py; frozen)
SELECT
  l_orderkey,
  SUM(l_extendedprice * (
    1 - l_discount
  )) AS revenue,
  o_orderdate,
  o_shippriority
FROM customer, orders, lineitem
WHERE
  $1 = c_mktsegment
  AND o_custkey = c_custkey
  AND o_orderkey = l_orderkey
  AND $2 > o_orderdate
  AND $2 < l_shipdate
GROUP BY
  l_orderkey,
  o_orderdate,
  o_shippriority
ORDER BY
  revenue DESC,
  o_orderdate
LIMIT 10
